14	function ctx({ files = [], pkg }) {
15	  const disk = new Set([...files, 'package.json']);
16	  return {
17	    files,
18	    read: (p) => (p === 'package.json' ? JSON.stringify(pkg) : null),
19	    exists: (p) => disk.has(p),
20	  };
21	}
22	
23	const pkgWith = (offline) => ({ scripts: { 'test:offline': `node --test ${offline.join(' ')}` } });
24	
25	test('test-offline-list-sync: fires when a mirror test is missing from the list', () => {
26	  const findings = testOfflineListSync.run(
27	    ctx({
28	      files: ['extension-test/a.test.js', 'extension-test/b.test.js'],
29	      pkg: pkgWith(['extension-test/a.test.js']),
30	    }),
31	  );
32	  assert.equal(findings.length, 1);
33	  assert.match(findings[0].what, /missing extension-test\/b\.test\.js/);
34	  assert.equal(findings[0].severity, 'blocking');
35	});
36	
37	test('test-offline-list-sync: fires when the list names a file that does not exist', () => {
38	  const findings = testOfflineListSync.run(
39	    ctx({
40	      files: ['extension-test/a.test.js'],
41	      pkg: pkgWith(['extension-test/a.test.js', 'extension-test/gone.test.js']),
42	    }),
43	  );
44	  assert.equal(findings.length, 1);
45	  assert.match(findings[0].what, /extension-test\/gone\.test\.js, which does not exist/);
46	});
47	
48	test('test-offline-list-sync: quiet when list and tree agree (non-mirror entries ignored)', () => {
49	  const findings = testOfflineListSync.run(
50	    ctx({
51	      files: ['extension-test/a.test.js', 'dev/build/test/other.test.js'],
52	      pkg: pkgWith(['extension-test/a.test.js', 'dev/build/release/shipping-files.test.js']),
53	    }),
54	  );
55	  assert.deepEqual(findings, []);
56	});
57	
58	test('test-offline-list-sync: quiet when package.json has no test:offline script', () => {
59	  const findings = testOfflineListSync.run(
60	    ctx({ files: ['extension-test/a.test.js'], pkg: { scripts: {} } }),
61	  );
62	  assert.deepEqual(findings, []);
63	});
