65	// A context whose files ARE the keys of a path → content map, for the rules that
66	// read file text rather than package.json.
67	const treeCtx = (tree) => ({
68	  files: Object.keys(tree),
69	  read: (p) => (p in tree ? tree[p] : null),
70	  exists: (p) => p in tree,
71	});
