73	test('custom-sources-flat: fires on a subdirectory, a non-source file, and a pipeline file in custom/', () => {
74	  const findings = customSourcesFlat.run(
75	    treeCtx({
76	      'extension/event-extractors/custom/barby.js': '',
77	      'extension/event-extractors/custom/shared/util.js': '',
78	      'extension/event-extractors/custom/README.md': '',
79	      'extension/event-extractors/custom/generic-extractor.js': '',
80	    }),
81	  );
