83	  assert.match(findings[0].what, /sits in a subdirectory/);
84	  assert.match(findings[1].what, /is not a per-site source/);
85	  assert.match(findings[2].what, /is a pipeline file/);
86	  assert.ok(findings.every((f) => f.severity === 'blocking'));
87	});
