103	// npm-test-glob-coverage reads package.json's `test` (and `test:e2e`) scripts, so its
104	// fixtures pair a file list with a scripts object — the real shape of both scripts,
105	// quoted globs included.
106	const globCtx = (files, scripts) =>
107	  ctx({ files, pkg: { scripts } });
